/**
 * The content-defined chunker, ported from `omni-chunk`.
 *
 * Boundaries must match the Rust chunker or a vault and a desktop daemon never
 * deduplicate. The rolling hash is `h = (h << 1) + GEAR[byte]` in 64-bit
 * wrapping arithmetic, and the boundary test is `h & (avg-1) == 0`. Only the
 * low 18 bits matter for that test, so a uint32 accumulator is *exact*, not an
 * approximation; the gear table is generated from the same splitmix64 stream
 * and truncated to its low 32 bits.
 *
 * `testdata/chunk_vectors.json` is generated by
 * `cargo run -p omni-chunk --example gen_vectors` and asserted in
 * `tests/chunker.test.ts`. Do not edit the constants without regenerating it.
 */

export interface Chunk {
  offset: number;
  len: number;
}

export const CHUNK_CONFIG = {
  min: 64 * 1024,
  avg: 256 * 1024,
  max: 1024 * 1024,
} as const;

const MASK = (nextPowerOfTwo(CHUNK_CONFIG.avg) - 1) >>> 0;

const GEAR: Uint32Array = buildGear();

function nextPowerOfTwo(value: number): number {
  let out = 1;
  while (out < value) out <<= 1;
  return out;
}

/** 256 fixed constants, one per byte, from splitmix64. */
function buildGear(): Uint32Array {
  const table = new Uint32Array(256);
  const mask = (1n << 64n) - 1n;
  let state = 0x9e3779b97f4a7c15n;
  for (let at = 0; at < 256; at += 1) {
    // `state = splitmix(state)`: the *mixed* value feeds the next round, not
    // the incremented one. Getting this wrong changes every constant and every
    // boundary, which is exactly what the golden vectors check.
    state = (state + 0x9e3779b97f4a7c15n) & mask;
    let z = state;
    z = ((z ^ (z >> 30n)) * 0xbf58476d1ce4e5b9n) & mask;
    z = ((z ^ (z >> 27n)) * 0x94d049bb133111ebn) & mask;
    z = (z ^ (z >> 31n)) & mask;
    table[at] = Number(z & 0xffffffffn);
    state = z;
  }
  return table;
}

/** Cut `data` at content-defined boundaries. */
export function split(data: Uint8Array): Chunk[] {
  const chunks: Chunk[] = [];
  let start = 0;
  let hash = 0;
  for (let at = 0; at < data.length; at += 1) {
    hash = (((hash << 1) >>> 0) + (GEAR[data[at]!] ?? 0)) >>> 0;
    const size = at - start + 1;
    if (size >= CHUNK_CONFIG.max || (size >= CHUNK_CONFIG.min && (hash & MASK) === 0)) {
      chunks.push({ offset: start, len: size });
      start = at + 1;
      hash = 0;
    }
  }
  if (start < data.length) {
    chunks.push({ offset: start, len: data.length - start });
  }
  return chunks;
}

/** Lowercase-hex SHA-256 of `bytes`, the chunk address. */
export async function sha256Hex(bytes: Uint8Array): Promise<string> {
  // A fresh buffer: `bytes` may be a view into a larger one.
  const digest = await crypto.subtle.digest("SHA-256", bytes.slice().buffer);
  return toHex(new Uint8Array(digest));
}

export function toHex(bytes: Uint8Array): string {
  let out = "";
  for (const byte of bytes) {
    out += byte.toString(16).padStart(2, "0");
  }
  return out;
}

/** Concatenate chunks in order. */
export function joinChunks(parts: Uint8Array[]): Uint8Array {
  let total = 0;
  for (const part of parts) total += part.length;
  const out = new Uint8Array(total);
  let at = 0;
  for (const part of parts) {
    out.set(part, at);
    at += part.length;
  }
  return out;
}
